-- Integration SQL: all fixtures and writes are rolled back; no Storage writes.
begin;
do $$
declare provider_auth uuid; provider_user integer; pid integer; balai_a integer; balai_b integer; kind integer; other_kind integer; tpl integer; org integer; team integer; team2 integer; other_team integer; tool integer; state jsonb; before_snapshot jsonb; before_provider integer; r record; expected_a boolean; expected_b boolean; n integer;
begin
 select u.pengguna_id,u.auth_user_id into provider_user,provider_auth from public.pengguna u join public.pengguna_peran pp using(pengguna_id) join public.peran pr using(peran_id) where pr.nama='penyedia_jasa' limit 1;
 select p.paket_id,p.balai_id,p.penyedia_id,q.snapshot_pengajuan,q.template_id into pid,balai_a,before_provider,before_snapshot,tpl from public.paket_kontrak p join public.checklist_pengisian q using(paket_id) join public.checklist_template t using(template_id) where q.status='DISETUJUI' and t.no_dokumen='JM-PERSIAPAN-TAHAP0' order by p.paket_id limit 1;
 if pid is null then raise exception 'Need an approved preparation package';end if;
 select jenis_survei_id into kind from public.jenis_survei where kode='IRI';select jenis_survei_id into other_kind from public.jenis_survei where kode='PCI';
 select min(scope_balai_id) into balai_b from public.pengguna_peran where scope_balai_id<>balai_a;
 if (select count(*) from public.jenis_survei)<>8 then raise exception 'Expected eight named survey types';end if;
 if exists(select 1 from public.jenis_survei where metode_uji is not null or satuan_volume is not null or sistem_id is not null or semester_wajib is not null) then raise exception 'Unverified catalog metadata filled';end if;
 perform set_config('request.jwt.claim.sub',provider_auth::text,true);
 -- Fail provider audit: registration must roll back.
 alter table public.audit_trail add constraint test_provider_audit_failure check(aksi<>'CREATE_PROVIDER') not valid;
 execute 'set local role authenticated';
 begin perform public.daftar_penyedia_tunggal('Rollback organisation');raise exception 'Provider audit not enforced';exception when check_violation then null;end;
 execute 'reset role';alter table public.audit_trail drop constraint test_provider_audit_failure;
 execute 'set local role authenticated';
 state:=public.daftar_penyedia_tunggal(' UJIAN - Organisasi rollback ');org:=(state->>'penyedia_id')::int;
 if state->>'nama'<>'UJIAN - Organisasi rollback' then raise exception 'Name not trimmed';end if;
 begin perform public.daftar_penyedia_tunggal('Second organisation');raise exception 'Second organisation allowed';exception when unique_violation then null;end;
 begin perform public.daftar_tim_survei(pid,2147483647,kind,'Bad org');raise exception 'Unknown org allowed';exception when invalid_parameter_value then null;end;
 begin perform public.daftar_tim_survei(pid,org,2147483647,'Bad kind');raise exception 'Unknown survey allowed';exception when invalid_parameter_value then null;end;
 execute 'reset role';
 alter table public.audit_trail add constraint test_team_audit_failure check(aksi<>'CREATE_SURVEY_TEAM') not valid;
 execute 'set local role authenticated';
 begin perform public.daftar_tim_survei(pid,org,kind,'Rollback team');raise exception 'Team audit not enforced';exception when check_violation then null;end;
 execute 'reset role';
 if (select penyedia_id from public.paket_kontrak where paket_id=pid) is distinct from before_provider then raise exception 'Failed team left provider link';end if;
 alter table public.audit_trail drop constraint test_team_audit_failure;
 execute 'set local role authenticated';
 state:=public.daftar_tim_survei(pid,org,kind,' Tim IRI Ujian ');team:=(state->>'tim_id')::int;
 if state->>'nama_tim'<>'Tim IRI Ujian' then raise exception 'Team name not trimmed';end if;
 begin perform public.daftar_tim_survei(pid,org,kind,'tim iri ujian');raise exception 'Duplicate team allowed';exception when unique_violation then null;end;
 state:=public.daftar_tim_survei(pid,org,kind,'Tim IRI Kedua');team2:=(state->>'tim_id')::int;
 state:=public.daftar_tim_survei(pid,org,other_kind,'Tim PCI Ujian');other_team:=(state->>'tim_id')::int;
 execute 'reset role';
 alter table public.audit_trail add constraint test_tool_audit_failure check(aksi<>'ASSIGN_EQUIPMENT') not valid;
 execute 'set local role authenticated';
 begin perform public.daftar_alat_tim(pid,team,'{"nama_alat":"Alat Ujian","nomor_seri":"ROLLBACK-TOOL-01","kondisi":"Belum diperiksa","milik_djbm":false}');raise exception 'Tool audit not enforced';exception when check_violation then null;end;
 execute 'reset role';
 if exists(select 1 from public.alat_survei where nomor_seri='ROLLBACK-TOOL-01') then raise exception 'Failed assignment left tool';end if;
 alter table public.audit_trail drop constraint test_tool_audit_failure;
 execute 'set local role authenticated';
 state:=public.daftar_alat_tim(pid,team,'{"nama_alat":"Alat Ujian","nomor_seri":"ROLLBACK-TOOL-01","kondisi":"Belum diperiksa","milik_djbm":false,"tahun_perolehan":2026,"mulai":"2026-10-18"}');tool:=(state#>>'{alat,alat_id}')::int;
 if state#>>'{alat,jenis_survei_id}'<>kind::text or state#>>'{alat,penyedia_id}'<>org::text or state->>'kalibrasi_belum_dinilai'<>'true' then raise exception 'Tool context was not server-derived';end if;
 execute 'reset role';
 if (select count(*) from public.kalibrasi_alat)<>0 then raise exception 'Registration invented calibration';end if;
 execute 'set local role authenticated';
 perform public.daftar_alat_tim(pid,team2,jsonb_build_object('alat_id',tool));
 begin perform public.daftar_alat_tim(pid,team2,jsonb_build_object('alat_id',tool));raise exception 'Duplicate assignment allowed';exception when unique_violation then null;end;
 begin perform public.daftar_alat_tim(pid,other_team,jsonb_build_object('alat_id',tool));raise exception 'Wrong survey equipment assigned';exception when invalid_parameter_value then null;end;
 begin perform public.daftar_alat_tim(pid,2147483647,jsonb_build_object('alat_id',tool));raise exception 'Wrong team allowed';exception when no_data_found then null;end;
 begin perform public.daftar_alat_tim(pid,team,'{"nama_alat":"Duplicate","nomor_seri":"ROLLBACK-TOOL-01","kondisi":"Unknown","milik_djbm":false}');raise exception 'Duplicate serial allowed';exception when unique_violation then null;end;
 begin perform public.daftar_alat_tim(pid,team,'{"nama_alat":"Bad","nomor_seri":"BAD-DATE","kondisi":"Unknown","milik_djbm":false,"mulai":"2026-02-30"}');raise exception 'Invalid date allowed';exception when invalid_parameter_value then null;end;
 begin perform public.daftar_alat_tim(pid,team,'{"nama_alat":"Bad","nomor_seri":"BAD-FIELD","kondisi":"Unknown","milik_djbm":false,"status":"LULUS"}');raise exception 'Fake pass allowed';exception when invalid_parameter_value then null;end;
 execute 'reset role';
 insert into public.paket_kontrak(paket_id,balai_id,nama_paket,status) overriding system value values(2100000010,balai_b,'Rollback package B','DRAFT');
 insert into public.checklist_pengisian(paket_id,template_id,status) values(2100000010,tpl,'DRAFT');
 execute 'set local role authenticated';
 begin perform public.daftar_tim_survei(2100000010,org,kind,'Not yet approved');raise exception 'Unapproved package allowed';exception when object_not_in_prerequisite_state then null;end;
 execute 'reset role';update public.checklist_pengisian set status='DISETUJUI' where paket_id=2100000010;
 execute 'set local role authenticated';
 state:=public.daftar_tim_survei(2100000010,org,kind,'Tim package B');other_team:=(state->>'tim_id')::int;
 begin perform public.daftar_alat_tim(pid,other_team,jsonb_build_object('alat_id',tool));raise exception 'Cross-package team allowed';exception when no_data_found then null;end;
 perform public.daftar_alat_tim(2100000010,other_team,'{"nama_alat":"Alat B","nomor_seri":"ROLLBACK-TOOL-B","kondisi":"Belum diperiksa","milik_djbm":false}');
 execute 'reset role';
 -- Every account's rows and direct RPC restrictions.
 for r in select u.auth_user_id,u.pengguna_id,pr.nama,pp.scope_balai_id,pp.scope_paket_id from public.pengguna u join public.pengguna_peran pp using(pengguna_id) join public.peran pr using(peran_id) loop
  expected_a:=r.nama in ('penyedia_jasa','admin','direktorat') or (r.nama='pic_balai' and r.scope_balai_id=balai_a and (r.scope_paket_id is null or r.scope_paket_id=pid));
  expected_b:=r.nama in ('penyedia_jasa','admin','direktorat') or (r.nama='pic_balai' and r.scope_balai_id=balai_b and (r.scope_paket_id is null or r.scope_paket_id=2100000010));
  perform set_config('request.jwt.claim.sub',r.auth_user_id::text,true);execute 'set local role authenticated';
  if (select count(*) from public.tim_survei where tim_id=team)<>(case when expected_a then 1 else 0 end) then raise exception 'Team scope failed';end if;
  if (select count(*) from public.penugasan_alat where tim_id=team)<>(case when expected_a then 1 else 0 end) then raise exception 'Assignment scope failed';end if;
  if (select count(*) from public.alat_survei where alat_id=tool)<>(case when expected_a then 1 else 0 end) then raise exception 'Tool scope failed';end if;
  if (select count(*) from public.tim_survei where tim_id=other_team)<>(case when expected_b then 1 else 0 end) then raise exception 'Other Balai scope failed';end if;
  if (select count(*) from public.penyedia_jasa where penyedia_id=org)<>(case when expected_a or expected_b then 1 else 0 end) then raise exception 'Organisation scope failed';end if;
  if (select count(*) from public.jenis_survei)<>8 then raise exception 'Catalog access failed';end if;
  if r.nama<>'penyedia_jasa' then
   begin perform public.daftar_penyedia_tunggal('Not allowed');raise exception 'Role created org';exception when insufficient_privilege then null;end;
   begin perform public.daftar_tim_survei(pid,org,kind,'Not allowed');raise exception 'Role created team';exception when insufficient_privilege then null;end;
   begin perform public.daftar_alat_tim(pid,team,jsonb_build_object('alat_id',tool));raise exception 'Role assigned tool';exception when insufficient_privilege then null;end;
  end if;
  if has_table_privilege(current_user,'public.alat_survei','INSERT') or has_table_privilege(current_user,'public.tim_survei','UPDATE') or has_table_privilege(current_user,'public.penugasan_alat','DELETE') then raise exception 'Direct writes granted';end if;
  execute 'reset role';
 end loop;
 if (select snapshot_pengajuan from public.checklist_pengisian where paket_id=pid and template_id=tpl)<>before_snapshot then raise exception 'Stage 0 snapshot changed';end if;
 update public.pengguna set terkunci=true where pengguna_id=provider_user;
 perform set_config('request.jwt.claim.sub',provider_auth::text,true);execute 'set local role authenticated';
 begin perform public.daftar_tim_survei(pid,org,kind,'Locked');raise exception 'Locked profile allowed';exception when insufficient_privilege then null;end;
 if exists(select 1 from public.jenis_survei) or exists(select 1 from public.alat_survei) then raise exception 'Locked profile reads catalog/tools';end if;
 execute 'reset role';
 if has_function_privilege('anon','public.daftar_alat_tim(integer,integer,jsonb)','EXECUTE') or has_function_privilege('anon','public.daftar_tim_survei(integer,integer,integer,text)','EXECUTE') or has_function_privilege('anon','public.daftar_penyedia_tunggal(text)','EXECUTE') then raise exception 'Anon RPC granted';end if;
end $$;
rollback;
select 'PASS: single provider, team/provider linkage, new/reused equipment, survey and package matching, duplicate serial/team/assignment, date validation, approval gate, all-account RLS and write denial, locked profile, audit rollback, and preserved preparation snapshot. Fixtures rolled back.' as verification;
